//! Canonical HTMLLabelElement.htmlFor reflects exact native label attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><label id=label for=seed>Choice</label><input id=field type=checkbox><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://label-for-accessor.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn html_label_for_accessor_canonical_descriptors_prototype_and_native_units(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var label=document.getElementById('label'),descriptor=Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'htmlFor');if(Object.getPrototypeOf(label)!==HTMLLabelElement.prototype||Object.getPrototypeOf(HTMLLabelElement.prototype)!==HTMLElement.prototype||label.constructor!==HTMLLabelElement||!(label instanceof HTMLLabelElement)||Object.prototype.toString.call(label)!=='[object HTMLLabelElement]'||!descriptor||!descriptor.enumerable||!descriptor.configurable||typeof descriptor.get!=='function'||typeof descriptor.set!=='function'||Object.hasOwn(label,'htmlFor')||label.htmlFor!=='seed')throw 'canonical native label interface';var caught=false;try{new HTMLLabelElement();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal native label construction';label.htmlFor='A\ud800z';var a=label.getAttributeNode('for');if(label.htmlFor!=='A\ud800z'||descriptor.get.call(label)!==a.value||label.htmlFor==='A�z')throw 'exact native accessor';descriptor.set.call(label,'B\udfffz');if(a!==label.getAttributeNode('for')||a.value!=='B\udfffz'||label.htmlFor!==a.value)throw 'actual saved native setter';"#);}
#[test]
fn html_label_for_accessor_inert_html_namespace_clone_import_adoption_and_author_shadow(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createDocument(null,'Root'),source=owner.createElementNS('http://www.w3.org/1999/xhtml','label'),descriptor=Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'htmlFor');source.htmlFor='A\ud800z';var a=source.getAttributeNode('for'),copy=source.cloneNode(true),target=document.implementation.createHTMLDocument('target'),imported=target.importNode(source,true);if(Object.getPrototypeOf(source)!==HTMLLabelElement.prototype||copy.htmlFor!==source.htmlFor||imported.htmlFor!==source.htmlFor||copy.ownerDocument!==owner||imported.ownerDocument!==target||copy.getAttributeNode('for')===a)throw 'real independent label records';var hits=0;Object.defineProperty(source,'htmlFor',{get:function(){hits++;return 'author';},configurable:true});var main=document.importNode(source,true);if(hits||main.htmlFor!=='A\ud800z'||descriptor.get.call(source)!=='A\ud800z')throw 'clone ignores author properties';target.adoptNode(source);descriptor.set.call(source,'fresh');if(source.getAttributeNode('for')!==a||a.ownerDocument!==target||a.value!=='fresh'||copy.htmlFor!=='A\ud800z'||source.htmlFor!=='author')throw 'real adopted label identity';"#);}
#[test]
fn html_label_for_accessor_domstring_conversion_namespace_identity_and_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('label'),descriptor=Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'htmlFor');source.setAttributeNS('urn:attribute','for','foreign');var a=source.getAttributeNodeNS(null,'for'),foreign=source.getAttributeNodeNS('urn:attribute','for'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});source.htmlFor=null;source.htmlFor=undefined;descriptor.set.call(source);descriptor.set.call(source,'A\ud800z');if(source.htmlFor!=='A\ud800z'||source.getAttributeNodeNS(null,'for')!==a||foreign.value!=='foreign'||foreign.ownerElement!==source)throw 'null namespace and actual native Attr';var records=watch.takeRecords();if(records.length!==4||records[0].oldValue!=='seed'||records[1].oldValue!=='null'||records[2].oldValue!=='undefined'||records[3].oldValue!=='undefined'||records[3].attributeName!=='for'||records[3].attributeNamespace!==null)throw 'DOMString conversion and exact observations';source.removeAttribute('for');if(source.htmlFor!==''||descriptor.get.call(source)!==''||a.ownerElement!==null||a.value!=='A\ud800z'||foreign.value!=='foreign')throw 'missing empty native reflection';"#);}

#[test]
fn html_label_for_accessor_native_brand_conversion_and_author_prototype_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var label=document.getElementById('label'),descriptor=Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'htmlFor'),calls=0;if(descriptor.get.name!=='get htmlFor'||descriptor.set.name!=='set htmlFor'||descriptor.get.length!==0||descriptor.set.length!==1)throw 'canonical accessor metadata';var owner=new Document(),foreign=owner.createElementNS('urn:element','label'),html=owner.createElementNS('http://www.w3.org/1999/xhtml','div');for(var bad of [{},Object.create(HTMLLabelElement.prototype),document,foreign,html]){var caught=false;try{descriptor.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine HTML label setter brand';caught=false;try{descriptor.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine HTML label getter brand';}if(calls)throw 'brand before author conversion';var caught=false;try{label.htmlFor=Symbol('bad');}catch(e){caught=e instanceof TypeError;}if(!caught||label.htmlFor!=='seed')throw 'Symbol before native publication';var marker={};caught=false;try{label.htmlFor={toString:function(){label.setAttribute('for','effect');throw marker;}};}catch(e){caught=e===marker;}if(!caught||label.htmlFor!=='effect')throw 'abrupt author effects';label.htmlFor={toString:function(){calls++;label.setAttribute('for','reentered');return 'A\ud800z';}};if(calls!==1||label.htmlFor!=='A\ud800z')throw 'once conversion and current native state';var keys=[];for(var key in label)if(key==='htmlFor')keys.push(key);if(keys.length!==1||Object.keys(label).length)throw 'inherited enumerable native accessor';Object.defineProperty(label,'htmlFor',{value:'own',writable:true,enumerable:true,configurable:true});if(label.htmlFor!=='own'||descriptor.get.call(label)!=='A\ud800z')throw 'author own shadow separated from native';delete label.htmlFor;Object.defineProperty(HTMLLabelElement.prototype,'htmlFor',{get:function(){return 'prototype';},configurable:true});if(label.htmlFor!=='prototype'||descriptor.get.call(label)!=='A\ud800z')throw 'ordinary author prototype override';delete HTMLLabelElement.prototype.htmlFor;if(label.htmlFor!==undefined||descriptor.get.call(label)!=='A\ud800z')throw 'prototype deletion and saved native accessor';Object.defineProperty(HTMLLabelElement.prototype,'htmlFor',descriptor);label.htmlFor='fresh';if(label.htmlFor!=='fresh')throw 'native descriptor restoration';"#);}
#[test]
fn html_label_for_accessor_read_limits_and_cancellation_preserve_actual_record(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var label=document.getElementById('label');label.htmlFor='A\ud800z';"#);let label=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("label")).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);let strings=p.state.limits.host.string_bytes;for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=4,_=>p.state.execution_deadline=Some(Instant::now())};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_label_for_get(node_handle(label)).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;}p.begin_job();run(&mut d,&mut f,&mut p,"if(label.htmlFor!=='A\\ud800z')throw 'fresh exact read recovery';");}
#[test]
fn html_label_for_accessor_no_main_slot_prototype_and_independent_snapshots(){let(mut d,mut f,mut p)=fixture();let count=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=count;run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','label');source.htmlFor='A\ud800z';var a=source.getAttributeNode('for'),copy=source.cloneNode(true);if(!(source instanceof HTMLLabelElement)||copy.htmlFor!==source.htmlFor||a.ownerDocument!==owner)throw 'no main slot native label';source.htmlFor='fresh';if(copy.htmlFor!=='A\ud800z'||a.value!=='fresh')throw 'independent no-slot values';"#);assert_eq!(d.nodes.len(),count);p.state.node_limit=limit;}

#[test]
fn html_label_for_accessor_writer_resource_refusal_cancellation_and_namespace_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('label');source.setAttributeNS('urn:attribute','for','foreign');source.htmlFor='A\ud800z';var a=source.getAttributeNodeNS(null,'for'),foreign=source.getAttributeNodeNS('urn:attribute','for'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});"#);let before=format!("{:?}",d.nodes);let state=(p.state.attributes.len(),p.state.dom_commits,p.state.retained);let retained=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;for mode in 0..5{for expression in [r#"source.htmlFor='longB\udfffz';"#,"source.removeAttribute('for');"]{if mode==3&&!expression.contains("long"){continue;}p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=0,3=>p.state.limits.host.string_bytes=4,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("mode {mode}, {expression}"));assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.attributes.len(),p.state.dom_commits,p.state.retained),state);p.state.retained_limit=retained;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;}}p.begin_job();run(&mut d,&mut f,&mut p,r#"if(a.value!=='A\ud800z'||foreign.value!=='foreign'||watch.takeRecords().length)throw 'refusal native state';a.value='B\udfffz';source.removeAttribute('for');var records=watch.takeRecords();if(a.ownerElement!==null||a.value!=='B\udfffz'||foreign.ownerElement!==source||foreign.value!=='foreign'||records.length!==2||records[0].oldValue!=='A\ud800z'||records[1].oldValue!=='B\udfffz')throw 'exact fresh recovery';"#);}

#[test]
fn html_label_for_accessor_saved_child_origin_precedes_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var source=document.getElementById('label'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLLabelElement.prototype,'htmlFor'),calls=0;descriptor.set.call(source,'A\ud800z');"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://other-label-for.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("descriptor.set.call(source,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://label-for-accessor.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||source.getAttribute('for')!=='A\\ud800z')throw 'origin before conversion';descriptor.set.call(source,'fresh');if(source.getAttribute('for')!=='fresh')throw 'fresh origin recovery';");}

